"""R64 S6 batch B16+B17+B18 prediction writer. Reads only batches.json for id assertion."""
import json, os
BASE = '/home/hatch/workspace/divination/benchmark/phase3/runs/round64'
batches = json.load(open(os.path.join(BASE, 'batches.json')))
MY = []
for k in ('B16', 'B17', 'B18'):
    MY += batches[k]
assert len(MY) == 60, len(MY)

def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

