# ---------------- main ----------------
outdir = os.path.join(BASE, 'predictions')
os.makedirs(outdir, exist_ok=True)
assert set(P.keys()) == set(MY), (set(MY) - set(P.keys()), set(P.keys()) - set(MY))
for cid in MY:
    d = P[cid]
    rec = {"case_id": cid, "prediction_text": d['text'], "basis": d['basis'],
           "confidence": d['conf'], "trigger": d['trig']}
    with open(os.path.join(outdir, cid + '.json'), 'w', encoding='utf-8') as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
print('wrote', len(P), 'files')
